#include <coroutine>
#include <iostream>

// 1. A lightweight Awaitable structure representing a non-blocking asynchronous socket read
struct SocketReadAwaitable {
    int socket_fd;
    // 2. Poll socket immediately; return true if data is pre-buffered (no suspension needed)
    bool await_ready() { 
        return check_socket_buffer(socket_fd); 
    }
    // 3. Buffer is empty; register task handle with the epoll global scheduler loop
    void await_suspend(std::coroutine_handle<> handle) {
        register_with_epoll_loop(socket_fd, handle);
    }
    // 4. Socket has received data; wake up and return raw payload packets
    std::string await_resume() {
        return read_from_socket(socket_fd);
    }
};

// 1. Declare an asynchronous coroutine that queries a real-time market broker socket
Task<void> ingest_broker_feed(int socket_fd) {
    std::cout << "Initializing feed from socket " << socket_fd << "\n";
    while (true) {
        // 2. Suspend task and yield thread ownership back to event loop until socket events fire
        std::string raw_ticks = co_await SocketReadAwaitable{socket_fd};
        // 3. Re-awaken with zero OS context switcher cost; immediately process financial packet
        process_market_tick(raw_ticks);
    }
}
